using System;
using System.Collections.Generic;
namespace Downfield {
public static class MechanicsTests {
 static int checks,failures;static void Check(bool b,string n){checks++;if(!b){failures++;Console.WriteLine("FAIL Mechanics: "+n);}}
 static void Step(Simulation s,int frames,float x,float z){for(int i=0;i<frames;i++)s.Update(1f/60,x,z);}
 static Simulation New(bool practice){Simulation s=new Simulation(42);s.Practice=practice;s.NewGame();return s;}
 public static int Run(){Simulation s=New(true);Check(s.Clock==60,"one-minute quarters");s.Snap();Step(s,20,0,1);float before=s.Controlled.Z;s.Update(1f/60,0,0);Check(s.Controlled.Z==before&&s.Controlled.VX==0&&s.Controlled.VZ==0,"stick release plants feet without drift");Step(s,30,0,1);float speed=s.Controlled.VZ;s.Update(1f/60,0,-1);Check(s.Controlled.Pose=="cut"&&s.Controlled.VZ<speed,"hard reversal plants and loses momentum");
  s=New(true);s.Snap();s.Handoff();Step(s,40,0,0);s.Jump();Check(s.Controlled.Pose!="hurdle","jump gated behind line");s.Controlled.Z=s.Spot+3;s.Jump();Check(s.Controlled.Pose=="hurdle","jump uses separate action after line");Step(s,70,0,0);s.SkillMove(0,1);Check(s.Controlled.Pose=="truck"&&s.Controlled.Pose!="hurdle","right stick up trucks instead of jumping");float stamina=s.Controlled.Stamina;s.SkillMove(0,1);Check(s.Controlled.Stamina==stamina,"cannot spam moves during cooldown");
  s=New(true);s.Snap();Step(s,300,0,0);Player receiver=s.Receiver(0);float x=receiver.X,z=receiver.Z;Step(s,120,.4f,0);Check(Simulation.Distance(x,z,receiver.X,receiver.Z)>2,"scramble drill keeps receivers moving after routes end");
  HashSet<string> stunts=new HashSet<string>(),coverages=new HashSet<string>();int disguised=0;for(int i=0;i<120;i++){s=new Simulation(700+i);stunts.Add(s.RushPlan);coverages.Add(s.Coverage);if(s.Disguised)disguised++;}Check(stunts.Count==4,"straight rush plus three stunt plans");Check(coverages.Count==8&&disguised>30&&disguised<110,"eight coverages with varied disguised shells");
  // An elite receiver's speed advantage must create a real gap against the same trailing defender.
  Player fast=new Player(0,0,0,"WR",81,8.3f),slow=new Player(0,0,0,"WR",88,7);for(int i=0;i<180;i++){Simulation.GroundStep(fast,0,1,fast.Speed,1f/60);Simulation.GroundStep(slow,0,1,slow.Speed,1f/60);}Check(fast.Z-slow.Z>3,"speed produces spatial separation");
  s=New(false);s.Spot=80;s.FieldGoal();s.KickMeter=.5f;s.StopKick();Check(s.KickAnimating&&s.HomeScore==0,"meter starts animation before awarding points");float origin=s.KickBallZ;Step(s,50,0,0);Check(s.KickBallZ>origin&&s.KickBallHeight>1,"kick moves upward and forward");Step(s,86,0,0);Check(s.HomeScore==3&&s.State==Phase.Kickoff,"good kick resolves after visible flight");
  s=New(false);s.Spot=80;s.FieldGoal();s.KickMeter=1;s.StopKick();Step(s,125,0,0);Check(Math.Abs(s.KickBallX)>FieldGeometry.GoalHalfWidth&&s.HomeScore==0,"wide miss visibly passes outside uprights");s=New(false);s.FieldGoal();s.KickMeter=.5f;s.StopKick();Step(s,125,0,0);Check(s.KickBallZ<FieldGeometry.EndLine&&s.HomeScore==0,"out-of-range kick visibly falls short");
  Check(FieldGeometry.EndLine-FieldGeometry.GoalLine==10&&FieldGeometry.NearEndLine==-10,"end zones ten yards");Check(Math.Abs(FieldGeometry.GoalHalfWidth*6-18.5f)<.01f&&Math.Abs(FieldGeometry.CrossbarHeight*3-10)<.01f&&FieldGeometry.GoalBase>FieldGeometry.EndLine,"NFL goal width height and offset support");
  s=New(false);Check(s.SimDrive()&&s.SimulatedDrives==1&&s.State!=Phase.PreSnap,"simulate current possession");s.SimRest();Check(s.State==Phase.GameOver&&s.Quarter==4&&s.Clock==0,"simulate remaining game reaches final");
  // Measure simple sideline sprint exploits across independent defensive calls.
  int scores=0,stops=0;float gains=0,bestGain=-99;for(int i=0;i<60;i++){s=new Simulation(9000+i);s.Playbook=10;s.RunPlay=true;s.Snap();for(int frame=0;frame<900&&(s.State==Phase.Live||s.State==Phase.Flight);frame++){s.Sprint=true;s.Update(1f/60,s.Controlled.X<22?.8f:0,1);}gains+=s.Controlled.Z-20;bestGain=Math.Max(bestGain,s.Controlled.Z-20);if(s.HomeScore>0)scores++;else stops++;}Console.WriteLine("Run balance: "+scores+" TD / "+stops+" stops in 60 repeated sideline sprint trials; avg "+(gains/60).ToString("F1")+" best "+bestGain.ToString("F1"));Check(stops>35&&scores<20,"containment stops a repeated sideline sprint exploit");
  int catches=0,open=0,yac=0;float space=0;for(int seed=0;seed<120;seed++){s=new Simulation(seed+13000);s.Playbook=seed%6;s.Snap();Step(s,60,0,0);if(s.State!=Phase.Live)continue;Player r=s.Receiver(seed%5);float gap=99;foreach(Player d in s.Players)if(d.Team==1)gap=Math.Min(gap,Simulation.Distance(r.X,r.Z,d.X,d.Z));space+=gap;if(gap>2)open++;s.BeginPass(seed%5);s.ReleasePass();for(int frame=0;frame<180&&s.State==Phase.Flight;frame++)s.Update(1f/60,0,0);if(s.Completions>0){catches++;float catchSpot=s.Controlled.Z;for(int frame=0;frame<120&&s.State==Phase.Live;frame++)s.Update(1f/60,0,1);if(s.Controlled.Z-catchSpot>2)yac++;}}Console.WriteLine("Pass balance: "+catches+" catches / 120; "+open+" open before throw; "+yac+" gained >2 YAC; average separation "+(space/120).ToString("F1"));Check(open>25&&catches>30&&yac>8,"route separation allows meaningful catches and run after catch");Console.WriteLine("Mechanics: "+checks+" checks, "+failures+" failures");return failures;}
}
}
